-- Run once in Supabase → SQL Editor on the LIVE project, after 002_orders_and_admin.sql.
-- Brings the database catalog in line with the site: 18 products, 6 collections.
-- Generated from js/data.js. Safe to re-run: it updates rows in place and keeps orders untouched.
-- Stock is reset to the numbers in js/data.js, so re-run it only before real orders arrive.

BEGIN;

-- Product fields the site shows that the table did not have yet
ALTER TABLE products ADD COLUMN IF NOT EXISTS story TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS motif TEXT;

-- 1. COLLECTIONS ------------------------------------------------------------
INSERT INTO collections (name, slug, description, is_active, display_order) VALUES
  ($q$ALL$q$, $q$all$q$, $q$Every Bravadian design in one place. Oversized 240 GSM cotton tees with original Indian artwork.$q$, true, 0),
  ($q$ANIME$q$, $q$anime$q$, $q$Anime characters, manga-inspired artwork, Japanese animation.$q$, true, 1),
  ($q$MYTHOLOGY$q$, $q$mythology$q$, $q$Krishna, Shiva, Hanuman, Ramayana, Mahabharata, deities, mythological stories.$q$, true, 2),
  ($q$HERITAGE$q$, $q$heritage$q$, $q$Indian crafts, folk art, traditional patterns, architecture, cultural symbols, regional traditions.$q$, true, 3),
  ($q$STREET CULTURE$q$, $q$street-culture$q$, $q$Graffiti, urban graphics, hip-hop, typography, rebellious/contemporary designs.$q$, true, 4),
  ($q$MINIMAL$q$, $q$minimal$q$, $q$Simple typography, subtle symbols, clean graphics, understated designs.$q$, true, 5)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name, description = EXCLUDED.description,
  is_active = EXCLUDED.is_active, display_order = EXCLUDED.display_order, updated_at = NOW();

-- 2. PRODUCTS ---------------------------------------------------------------
