  collection_slug, tags, fabric, gsm, fit, material, sku, is_featured, is_new_drop, is_coming_soon,
  relic_tag, relic_badge, images, variants, status) VALUES
  ($q$prod-018$q$, $q$TRINETRA TEE$q$, $q$trinetra-tee$q$, $q$Shiva's third eye rising over the Himalaya, circled by the moon and the words See Beyond, printed large across the back, with a small BRAVADIAN mark on the front left chest. Oversized 240 GSM French Terry cotton, bio + silicone washed, DTF print.$q$, $q$Past, present, future, within. The third eye sees what the other two miss. A reminder to look past the obvious.$q$, NULL, 699, 999, NULL, $q$mythology$q$, ARRAY[$q$trinetra$q$, $q$shiva$q$, $q$third eye$q$, $q$mythology$q$, $q$oversized$q$, $q$240gsm$q$]::TEXT[], $q$240 GSM FRENCH TERRY // BIO + SILICONE WASH$q$, 240, $q$Oversized Drop-Shoulder$q$, $q$240 GSM French Terry Cotton, Bio + Silicone Washed$q$, $q$BRVD-TRN-06$q$, true, true, false, $q$DESIGN 06$q$, $q$NEW DROP$q$, $q${"front":"/images/products/trinetra/preview.webp"}$q$::jsonb, $q$[{"color":"Black","size":"S","stock":10},{"color":"Black","size":"M","stock":10},{"color":"Black","size":"L","stock":10},{"color":"Black","size":"XL","stock":10},{"color":"Black","size":"XXL","stock":10},{"color":"White","size":"S","stock":10},{"color":"White","size":"M","stock":10},{"color":"White","size":"L","stock":10},{"color":"White","size":"XL","stock":10},{"color":"White","size":"XXL","stock":10}]$q$::jsonb, $q$PUBLISHED$q$),
