ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, slug = EXCLUDED.slug, description = EXCLUDED.description,
  story = EXCLUDED.story, motif = EXCLUDED.motif,
  price = EXCLUDED.price, compare_price = EXCLUDED.compare_price, launch_price = EXCLUDED.launch_price,
  collection_slug = EXCLUDED.collection_slug, tags = EXCLUDED.tags, fabric = EXCLUDED.fabric,
  gsm = EXCLUDED.gsm, fit = EXCLUDED.fit, material = EXCLUDED.material, sku = EXCLUDED.sku,
  is_featured = EXCLUDED.is_featured, is_new_drop = EXCLUDED.is_new_drop, is_coming_soon = EXCLUDED.is_coming_soon,
  relic_tag = EXCLUDED.relic_tag, relic_badge = EXCLUDED.relic_badge,
  images = EXCLUDED.images, variants = EXCLUDED.variants, status = EXCLUDED.status, updated_at = NOW();

-- 3. REMOVE OLD STARTER COLLECTIONS (garuda, asura, chola, ...) no product uses any more
DELETE FROM collections c
 WHERE c.slug NOT IN ($q$all$q$, $q$anime$q$, $q$mythology$q$, $q$heritage$q$, $q$street-culture$q$, $q$minimal$q$)
   AND NOT EXISTS (SELECT 1 FROM products p WHERE p.collection_slug = c.slug);

COMMIT;

-- Check: expect 18 products and 6 collections
SELECT (SELECT count(*) FROM products) AS products, (SELECT count(*) FROM collections) AS collections;
